ValidationRule.errorConditionFormula:
IF( SEBCaseContactNoViolation__c < 1,

AND(
OR(AND( ISPICKVAL( Status__c , "Closed" ),
ISPICKVAL( PRIORVALUE(Status__c) , "Legal" ),
OR( Investigation_Legal_Recommend__c < 1,
Investigation_Recommend_Referral__c < 1,
Total_of_Allegations__c != Total_of_Allegation_Violations__c,
Total_of_Case_Contacts__c != Total_of_Case_Contact_Allegations__c,
Total_of_Case_Contacts__c != Total_of_Legal_Actions__c
)
)
)),
AND(
OR(AND( ISPICKVAL( Status__c , "Closed" ),
ISPICKVAL( PRIORVALUE(Status__c) , "Legal" ),
OR( Investigation_Legal_Recommend__c < 1,
Investigation_Recommend_Referral__c < 1,
Total_of_Case_Contacts__c != Total_of_Case_Contact_Allegations__c

)
)
))
)
